const dados = $json.body ?? $json;

if (dados.decisao !== 'aceita') return [];
if (!dados.data_hora_consulta) throw new Error('Horário da consultoria não informado.');

const partes = String(dados.data_hora_consulta).replace(' ', 'T');
const [ano, mes, dia] = partes.slice(0, 10).split('-');
const horario = partes.slice(11, 16);
if (!ano || !mes || !dia || !horario) throw new Error('Formato do horário da consultoria inválido.');

const telefone = String(dados.telefone_cliente ?? '').replace(/\D/g, '');
if (!telefone) throw new Error('Telefone do cliente não informado.');

return [{
  json: {
    telefone,
    prompt: `Escreva uma mensagem curta e cordial em português brasileiro para ${dados.nome_cliente || 'o cliente'} informando que a consultoria jurídica foi aprovada para ${dia}/${mes}/${ano} às ${horario}. Peça que responda ACEITO para confirmar ou RECUSO para informar que não poderá comparecer. Não invente informações. Retorne somente o texto da mensagem, sem aspas ou formatação.`
  }
}];

const proposta = $('Preparar proposta').first().json;
const partes = $json.candidates?.[0]?.content?.parts ?? [];
const mensagem = partes.map(parte => parte.text ?? '').join('').trim();
if (!mensagem) throw new Error('O Gemini não retornou o texto da proposta.');

return [{ json: { to: proposta.telefone, body: mensagem } }];

const evento = $json.body ?? $json;
const mensagens = Array.isArray(evento.messages) ? evento.messages : [];

return mensagens
  .filter(mensagem => !mensagem.from_me && mensagem.chat_id && mensagem.text?.body)
  .map(mensagem => ({
    json: {
      telefone: String(mensagem.chat_id).split('@')[0].replace(/\D/g, ''),
      mensagem: String(mensagem.text.body).trim()
    }
  }))
  .filter(item => item.json.telefone && item.json.mensagem);

const cliente = $('Ler resposta do cliente').item.json;
const partes = $json.candidates?.[0]?.content?.parts ?? [];
const texto = partes.map(parte => parte.text ?? '').join('').trim();
if (!texto) throw new Error('O Gemini não retornou uma resposta para o cliente.');

let resultado;
try {
  resultado = JSON.parse(texto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
} catch {
  throw new Error('O Gemini retornou uma resposta em formato inválido.');
}

const decisoes = ['aceita', 'recusada', 'duvida'];
if (!decisoes.includes(resultado.decisao) || !resultado.resposta) {
  throw new Error('A resposta do Gemini não contém uma decisão e mensagem válidas.');
}

return [{ json: { to: cliente.telefone, body: resultado.resposta } }];
